"use client";

import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { createClient } from "@/lib/sb/client";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { apiErrorMessage } from "@/lib/api-error-message";

type Profile = {
  avatar_url: string | null;
  username: string | null;
  bio: string | null;
};

type UserContextValue = {
  loading: boolean;
  error: string | null;
  profile: Profile | null;
  userEmail: string | null;
  roleId: "member" | "admin" | null;
  roleRank: number | null;
  refresh: () => Promise<void>;
};

const UserContext = createContext<UserContextValue | undefined>(undefined);

export function UserProvider({ children }: { children: React.ReactNode }) {
  // In demo mode (no Supabase env) there is no user to load — start settled.
  const configured = isSupabaseConfigured();
  const [loading, setLoading] = useState(configured);
  const [error, setError] = useState<string | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [roleId, setRoleId] = useState<"member" | "admin" | null>(null);
  const [roleRank, setRoleRank] = useState<number | null>(null);

  const load = async () => {
    if (!configured) return;
    try {
      setLoading(true);
      setError(null);
      // No session cookie: signed out. Asking the API would only log a 401
      // in the console of every signed-out page.
      const { data: session } = await createClient().auth.getSession();
      if (!session.session) {
        setProfile(null);
        setUserEmail(null);
        setRoleId(null);
        setRoleRank(null);
        return;
      }
      // Try up to 3 times with small backoff to allow session cookies to settle
      let lastErr: Error | null = null;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          const res = await fetch("/api/profile", {
            credentials: "include",
            cache: "no-store",
          });
          if (res.status === 401) {
            // Signed out — a normal state, not an error worth surfacing
            setProfile(null);
            setUserEmail(null);
            setRoleId(null);
            setRoleRank(null);
            lastErr = null;
            break;
          }
          if (!res.ok) {
            const body = await res.json().catch(() => ({}));
            throw new Error(apiErrorMessage(body, `Request failed (${res.status})`));
          }
          const data = (await res.json()) as {
            profile: Profile;
            email?: string | null;
            roleId?: "member" | "admin" | null;
            roleRank?: number | null;
          };
          setProfile(data.profile ?? null);
          setUserEmail(data.email ?? null);
          setRoleId(data.roleId ?? null);
          setRoleRank(data.roleRank ?? null);
          lastErr = null;
          break;
        } catch (e) {
          lastErr = e instanceof Error ? e : new Error(String(e));
          // small delay before retrying
          await new Promise((r) => setTimeout(r, 300 * (attempt + 1)));
        }
      }
      if (lastErr) throw lastErr;
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to fetch user profile");
      setProfile(null);
      setUserEmail(null);
      setRoleId(null);
      setRoleRank(null);
    } finally {
      setLoading(false);
    }
  };

  // biome-ignore lint/correctness/useExhaustiveDependencies: subscribe once on mount; load only reads setters
  useEffect(() => {
    if (!configured) return;
    void load();
    // Listen for auth state changes to proactively refresh user/profile
    const supabase = createClient();
    const { data: sub } = supabase.auth.onAuthStateChange((_event) => {
      // On SIGNED_IN, TOKEN_REFRESHED, SIGNED_OUT etc., try to reload
      void load();
    });
    return () => {
      sub?.subscription.unsubscribe();
    };
  }, []);

  // biome-ignore lint/correctness/useExhaustiveDependencies: load is recreated each render but behaves the same
  const value = useMemo<UserContextValue>(
    () => ({ loading, error, profile, userEmail, roleId, roleRank, refresh: load }),
    [loading, error, profile, userEmail, roleId, roleRank],
  );

  return <UserContext.Provider value={value}>{children}</UserContext.Provider>;
}

export function useUser(): UserContextValue {
  const ctx = useContext(UserContext);
  if (!ctx) {
    throw new Error("useUser must be used within a UserProvider");
  }
  return ctx;
}

"use client";

import { apiErrorMessage } from "@/lib/api-error-message";
import { type OrgMembership, orgSlugFromPath, repointOrgPath } from "@/lib/orgs/types";
import { createClient } from "@/lib/sb/client";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { usePathname, useRouter } from "next/navigation";
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";

/**
 * The one source of truth for tenancy on the client.
 *
 * Aveiro grew a UserProvider that carried organizations AND a separate
 * OrganizationProvider, and the switcher then had two lists that could
 * disagree. There is one provider here, and `UserProvider` stays about the
 * person — profile, email, global role — and knows nothing about tenants.
 *
 * The URL is what selects the organization, not state held here: `selected`
 * is derived from the `[org]` segment. That way a link, a refresh and a back
 * button all land on the same tenant as a click on the switcher, and there
 * is no second place for the selection to drift out of sync.
 */
type OrgContextValue = {
  /** Every organization the signed-in user belongs to. Empty in demo mode. */
  organizations: OrgMembership[];
  /** The one the URL is pointing at, once it is known. */
  selected: OrgMembership | null;
  /**
   * The `[org]` segment itself. Available before `organizations` loads, and
   * in demo mode where there is no database to load them from — so this, not
   * `selected`, is what a link builds a path from.
   */
  slug: string | null;
  /** Go to the same page under another organization. */
  select: (slug: string) => void;
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
};

const OrgContext = createContext<OrgContextValue | undefined>(undefined);

export function OrgProvider({ children }: { children: React.ReactNode }) {
  // Demo mode (no Supabase env): there is nothing to fetch, so start settled
  // rather than showing a spinner that will never resolve.
  const configured = isSupabaseConfigured();
  const pathname = usePathname() ?? "";
  const router = useRouter();

  const [organizations, setOrganizations] = useState<OrgMembership[]>([]);
  const [loading, setLoading] = useState(configured);
  const [error, setError] = useState<string | null>(null);

  const slug = orgSlugFromPath(pathname);

  const load = useCallback(async () => {
    if (!configured) return;
    try {
      setLoading(true);
      setError(null);

      // No session cookie: signed out, and the request would only log a 401.
      const { data: session } = await createClient().auth.getSession();
      if (!session.session) {
        setOrganizations([]);
        return;
      }

      const res = await fetch("/api/orgs", { credentials: "include", cache: "no-store" });

      // Signed out, or a composition running without Supabase configured:
      // normal states, not errors worth putting in front of anybody.
      if (res.status === 401 || res.status === 503) {
        setOrganizations([]);
        return;
      }
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(apiErrorMessage(body, `Request failed (${res.status})`));
      }

      const data = (await res.json()) as { organizations?: OrgMembership[] };
      setOrganizations(data.organizations ?? []);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load your organizations");
      setOrganizations([]);
    } finally {
      setLoading(false);
    }
  }, [configured]);

  // `load` is stable, so this runs once per mount. The list changes when an
  // organization is created or left, and both of those call refresh(), and
  // when the session does: signing in navigates on the client, so the
  // provider is still mounted from the signed-out page.
  useEffect(() => {
    void load();
    if (!configured) return;
    const { data: sub } = createClient().auth.onAuthStateChange((event) => {
      if (event === "SIGNED_IN" || event === "SIGNED_OUT") void load();
    });
    return () => sub.subscription.unsubscribe();
  }, [configured, load]);

  const value = useMemo<OrgContextValue>(() => {
    const selected = organizations.find((org) => org.slug === slug) ?? null;

    return {
      organizations,
      selected,
      slug,
      // Switching is a re-root of the current path, not a jump to a fixed
      // landing page: whoever switches stays on the page they were reading.
      select: (next: string) => {
        if (next !== slug) router.push(repointOrgPath(pathname, next));
      },
      loading,
      error,
      refresh: load,
    };
  }, [organizations, slug, pathname, loading, error, router, load]);

  return <OrgContext.Provider value={value}>{children}</OrgContext.Provider>;
}

export function useOrg(): OrgContextValue {
  const ctx = useContext(OrgContext);
  if (!ctx) {
    throw new Error("useOrg must be used within an OrgProvider");
  }
  return ctx;
}

import type { NextRequest } from "next/server";
import { authProxy } from "@/lib/sb/proxy";

/**
 * Every request but static assets, through each slice's step in turn: the
 * i18n slice maps a language URL (`/hu/store`) onto the page it renders, then
 * the auth slice rate-limits and refreshes the Supabase session for that
 * page. A composition without one of them has its step unwired here.
 */
export async function proxy(request: NextRequest) {
  return authProxy(request);
}

export const config = {
  // Everything that can touch auth — API routes included — but not static
  // assets. Refreshing the session in exactly one layer (here) keeps
  // Supabase's single-use refresh-token rotation from being lost.
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|trademarks|images|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|mp4)$).*)",
  ],
};

