    "rule": "Responsive xl/l/m/s/xs props exist only on Flex, Row, Column and Grid; Text and Heading take just s={{ hide: true }}. Button and the rest have none: to change one at a breakpoint, wrap it in a Row or Column and put the breakpoint prop there. Text and Heading take padding and flex but no radius or border; put those on the wrapper.",
    "inRules": true,
    "components": ["Flex", "Row", "Column", "Grid", "Button", "Text"]
  },
  "layout.noBaseline": {
    "rule": "vertical and horizontal take start, center, end, between, around, even or stretch. There is no baseline; for baseline-aligned text use style={{ alignItems: \"baseline\" }}.",
    "inRules": true,
    "components": ["Flex", "Row", "Column"]
  },
  "spacing.tokens": {
    "rule": "gap, padding and margin take spacing tokens (\"0\", \"1\", \"2\", \"4\", \"8\", \"12\", \"16\", \"20\", \"24\", \"32\", \"40\", \"48\", \"56\", \"64\", \"72\", \"80\", \"104\", \"128\", \"160\", or xs–xl). \"6\" and \"10\" are not tokens and are type errors.",
    "inRules": true,
    "components": ["Flex", "Row", "Column", "Grid"]
  },
  "layout.noSpanOrType": {
    "rule": "Row, Column and Grid have no span and no type prop. A clickable row is a Button (or a native <button>), and a Grid child spanning columns uses style={{ gridColumn: \"span 2\" }}.",
    "inRules": true,
    "components": ["Row", "Column", "Grid"]
  },
  "Column.form": {
    "rule": "Wrap a Column in a native <form onSubmit={handleSubmit}>. Column as=\"form\" keeps the div event types, so a FormEvent<HTMLFormElement> handler (and noValidate) is a type error.",
    "inRules": true,
    "components": ["Column", "Input", "Button"]
  },
  "Checkbox.checked": {
    "rule": "Checkbox, Switch and RadioButton take checked (or defaultChecked) and onToggle(checked: boolean). isChecked and isIndeterminate were 1.x; the 2.x props are checked and indeterminate.",
    "inRules": true,
    "components": ["Checkbox", "Switch", "RadioButton"]
  },
  "RevealFx.primaryContent": {
    "rule": "Never wrap primary content (headlines, prices, KPIs, CTAs) in RevealFx: it stays blurred and unreadable until the reveal ends. Reveal secondary sections only, with speed=\"fast\".",
    "inRules": true,
    "components": ["RevealFx"]
  },
  "size.rem": {
    "rule": "A number on width, height, minWidth or minHeight is rem, not px: width={32} is 512 px. For a pixel size write the spacing token string, width=\"32\" (32 px), or the rem value, width={2}. Token strings stop at the spacing scale (\"160\" is the largest), so height=\"320\" is a type error: write height={20}. An icon or avatar box is usually \"24\" to \"48\".",
    "inRules": true,
    "components": ["Flex", "Row", "Column", "Grid"]
  },
  "Chart.xAxis": {
    "rule": "The x axis reads the first key of data[0] that is not a series key (date, label, month). Put that key first in every point and list only the plotted keys in series: series={[{ key: \"visitors\" }]} with data={[{ date: \"Oct 1\", visitors: 1840 }]}.",
    "components": ["LineChart", "BarChart", "LineBarChart"]
  },
  "Map.positions": {
    "rule": "Positions are [longitude, latitude], not [lat, lng]. Map needs a height (or fill inside a sized parent); it shadows the global Map, so import it as another name in a file that also uses new Map().",
    "components": ["Map", "MapMarker", "MapMarkers", "MapPopup", "MapCircle"]
  }
}

import { requireOrg } from "@/lib/orgs/server";
import { isSupabaseConfigured } from "@/lib/sb/config";
import { notFound, redirect } from "next/navigation";

/**
 * The tenancy gate for everything under `/app/[org]`.
 *
 * The proxy already sends a signed-out visitor to `/auth`, but it only knows
 * whether there is a session — not whether this session belongs in THIS
 * organization. That question can only be answered against the database, so
 * it is answered here, once, for every page in the segment.
 *
 * A non-member gets a 404 rather than a 403: see the NOT_FOUND note in
 * src/lib/orgs/server.ts.
 */
export default async function OrgLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ org: string }>;
}) {
  // Demo mode: no Supabase at all, so there is no membership to check and
  // nothing to leak. Every composition has to run with zero environment
  // variables, and the product shell renders its sample data for any slug.
  //
  // Configured-but-incomplete is NOT this case: the guard below answers 503
  // and the segment 404s, which is the direction a tenancy gate should fail.
  if (!isSupabaseConfigured()) return <>{children}</>;

  const { org } = await params;
  const guard = await requireOrg(org);

  if (!guard.ok) {
    if (guard.status === 401) redirect("/auth");
    notFound();
  }

  return <>{children}</>;
}

/**
 * Shared tenancy types and URL helpers. Client-safe: this module imports
 * nothing server-only, so the provider and the switcher can use it too.
 * The guards live in `./server`, which must never be imported from a
 * client component.
 */
import type { TableQuerySpec } from "@/lib/data/query";
import { stripLocale } from "@/lib/i18n";

/**
 * Roles are a column on `organization_members`, not a table. Three of them,
 * the same three Aveiro settled on. An app that grows into per-resource
 * permissions layers a capability map on top — see docs/composition/
 * multi-tenancy.md, "Roles now, capabilities later".
 */
export type OrgRole = "owner" | "admin" | "member";

/** Ordered weakest to strongest; `roleAtLeast` compares on this. */
export const ORG_ROLES: readonly OrgRole[] = ["member", "admin", "owner"];

/** True when `role` is at least as strong as `minimum`. */
export function roleAtLeast(role: OrgRole, minimum: OrgRole): boolean {
  return ORG_ROLES.indexOf(role) >= ORG_ROLES.indexOf(minimum);
}

/** A row of `organizations`, as every read in this app selects it. */
export interface Organization {
  id: string;
  slug: string;
  name: string;
  personal: boolean;
  created_at: string;
}

/** An organization plus the signed-in user's role in it. */
export interface OrgMembership extends Organization {
  role: OrgRole;
}

/** A row of `organization_members`, for the members list. */
export interface OrgMember {
  user_id: string;
  role: OrgRole;
  /** The address they joined with; null on rows that predate the column. */
  email: string | null;
  created_at: string;
}

/** A member as the members table shows them: the row plus their profile. */
export interface OrgMemberRow extends OrgMember {
  username: string | null;
  full_name: string | null;
  avatar_url: string | null;
  /** The signed-in user's own row. */
  you: boolean;
}

/**
 * What the members table may sort and filter on. The route parses requests
 * with it and the Users page drives its DataTable with it, so the two cannot
 * disagree about which columns sort.
 */
export const MEMBERS_QUERY_SPEC: TableQuerySpec & { defaultSort: NonNullable<TableQuerySpec["defaultSort"]> } = {
  sortable: ["email", "role", "created_at"],
  filters: { role: ["owner", "admin", "member"] },
  defaultSort: { key: "created_at", direction: "asc" },
  defaultPerPage: 10,
};

/** An open invitation, as an admin sees it. The token is never stored or returned. */
export interface OrgInvitation {
  id: string;
  email: string;
  role: Exclude<OrgRole, "owner">;
  created_at: string;
  expires_at: string;
}

/**
 * The segment every org-scoped route hangs off.
 *
 * Deliberately not the URL root. A composed app shares its root with every
 * surface it was scaffolded with (`/docs`, `/store`, `/journal`, …), Next
 * resolves static segments before dynamic ones, and so a root-level org
 * slugged `store` would be shadowed by the store surface — and adding that
 * surface later would break a tenant that already existed. One dedicated
 * segment removes the whole class of problem, and nothing static lives
 * beside `[org]` under it.
 */
export const ORG_BASE = "/app";

/**
 * The slug used when Supabase is not configured. Every composition has to
 * build and run with no environment at all, so the org routes render for an
 * arbitrary slug in demo mode rather than 404ing on an empty database.
 */
export const DEMO_ORG_SLUG = "demo";

/** Where an invitation link points: `/invite/<token>`, outside `/app/`. */
export function invitationPathFor(token: string): string {
  return `/invite/${token}`;
}

/** `/app/acme` + an optional sub-path: `orgPath("acme", "/settings")`. */
export function orgPath(slug: string, subPath = ""): string {
  return `${ORG_BASE}/${slug}${subPath}`;
}

/** `^/app/<slug>(/rest)?$`, built from ORG_BASE so there is one source of truth. */
const ORG_PATH_RE = new RegExp(`^${ORG_BASE}/([^/]+)(/.*)?$`);

/**
 * The org slug in a pathname, or null when the path is not org-scoped.
 * `/app/acme/settings` -> `"acme"`, `/profile` -> `null`. A language prefix
 * is ignored: `/hu/app/acme` is the same tenant.
 */
export function orgSlugFromPath(pathname: string): string | null {
  return ORG_PATH_RE.exec(stripLocale(pathname))?.[1] ?? null;
}

/**
 * The same page under a different tenant: `/app/acme/settings` with `beta`
 * becomes `/app/beta/settings`. Switching organizations is a re-root, not a
 * navigation to a fixed landing page — the switcher keeps you where you are.
 * A path that is not org-scoped falls back to that org's home.
 */
export function repointOrgPath(pathname: string, slug: string): string {
  return orgPath(slug, ORG_PATH_RE.exec(stripLocale(pathname))?.[2] ?? "");
}

import { headers } from "next/headers";
import { LOCALE_HEADER, defaultLocale, locales, matchLocale } from "./index";

/**
 * The locale this request renders in. One language: the default, read without
 * touching the request, so pages stay static. Several: the one the i18n
 * slice's proxy took from the URL (`/hu/store`), which makes rendering
 * per-request.
 */
export async function getLocale(): Promise<string> {
  if (locales.length < 2) return defaultLocale;
  return matchLocale((await headers()).get(LOCALE_HEADER)) ?? defaultLocale;
}

