Now the Providers, which pass the whole config through to `ThemeProvider` (so tokens, scales, radius and density come from one place):

```tsx src/components/Providers.tsx
"use client";

import {
  type BorderStyle,
  DataThemeProvider,
  IconProvider,
  type NeutralColor,
  type ScalingSize,
  type Schemes,
  type SolidStyle,
  type SolidType,
  type SurfaceStyle,
  type Theme,
  ThemeProvider,
  ToastProvider,
  type TransitionStyle,
} from "@once-ui-system/core";
import type { ChartMode, ChartVariant } from "@once-ui-system/core/data";
// The Next adapters: links go through next/link and images through next/image.
import { LayoutProvider } from "@once-ui-system/core/next";
import { dataStyle, style } from "../resources/once-ui.config";
import { iconLibrary } from "../resources/icons";
import { OrgProvider } from "./OrgProvider";
import { UserProvider } from "./UserProvider";

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <LayoutProvider>
      <ThemeProvider
        theme={style.theme as Theme}
        defaultTheme={style.defaultTheme as Theme}
        brand={style.brand as Schemes}
        accent={style.accent as Schemes}
        neutral={style.neutral as NeutralColor}
        brandScale={style.brandScale}
        accentScale={style.accentScale}
        neutralScale={style.neutralScale}
        solid={style.solid as SolidType}
        solidStyle={style.solidStyle as SolidStyle}
        border={style.border as BorderStyle}
        surface={style.surface as SurfaceStyle}
        transition={style.transition as TransitionStyle}
        scaling={style.scaling as ScalingSize}
      >
        <DataThemeProvider
          variant={dataStyle.variant as ChartVariant}
          mode={dataStyle.mode as ChartMode}
          height={dataStyle.height}
          axis={{
            stroke: dataStyle.axis.stroke,
          }}
          tick={{
            fill: dataStyle.tick.fill,
            fontSize: dataStyle.tick.fontSize,
            line: dataStyle.tick.line,
          }}
        >
          <ToastProvider>
            <IconProvider icons={iconLibrary}>
              <UserProvider>
                <OrgProvider>{children}</OrgProvider>
              </UserProvider>
            </IconProvider>
          </ToastProvider>
        </DataThemeProvider>
      </ThemeProvider>
    </LayoutProvider>
  );
}
```

The root layout: no Google fonts, the font stacks set as CSS variables, and the full theme config handed to `ThemeInit`.

```tsx src/app/layout.tsx
import "@once-ui-system/core/css/styles.css";
import "@once-ui-system/core/css/tokens.css";
import "@/resources/custom.css";

import { Column, Flex, Meta, Schema, ThemeInit } from "@once-ui-system/core";
import { LocaleProvider, Providers } from "@/components";
import { getLocale } from "@/lib/i18n/server";
import { baseURL, dataStyle, fonts, landing, style } from "@/resources";

export async function generateMetadata() {
  return Meta.generate({
    title: landing.home.title,
    description: landing.home.description,
    baseURL: baseURL,
    // The site-wide defaults. No canonical here: each page names its own.
    image: landing.home.image,
  });
}

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const locale = await getLocale();

  return (
    <Flex
      suppressHydrationWarning
      data-scroll-behavior="smooth"
      as="html"
      lang={locale}
      fillWidth
      style={
        {
          [fonts.heading.variable]: fonts.heading.stack,
          [fonts.body.variable]: fonts.body.stack,
          [fonts.label.variable]: fonts.label.stack,
          [fonts.code.variable]: fonts.code.stack,
        } as React.CSSProperties
      }
    >
      <head>
        {/* A sync <script> is only allowed inside the document head. */}
        <Schema
          as="webPage"
          baseURL={baseURL}
          title={landing.home.title}
          description={landing.home.description}
          path={landing.home.path}
        />
        {/* Sets data-theme and the colour scheme before first paint. */}
        <ThemeInit
          config={{
            theme: style.theme,
            defaultTheme: style.defaultTheme,
            brand: style.brand,
            accent: style.accent,
            neutral: style.neutral,
            brandScale: style.brandScale,
            accentScale: style.accentScale,
            neutralScale: style.neutralScale,
            solid: style.solid,
            "solid-style": style.solidStyle,
            border: style.border,
            surface: style.surface,
            transition: style.transition,
            scaling: style.scaling,
            "viz-style": dataStyle.variant,
          }}
        />
      </head>
      <LocaleProvider locale={locale}>
        <Providers>
          <Column as="body" background="page" fillWidth margin="0" padding="0" minHeight="100vh">
            <Column fillWidth horizontal="center" flex={1}>
              {children}
            </Column>
          </Column>
        </Providers>
      </LocaleProvider>
    </Flex>
  );
}
```

The corner radius (2px) and the focus ring are not covered by a single typed token, so I'll set them in `custom.css` on the design system's own radius tokens rather than per element:

```css src/resources/custom.css
:root {
  --default-border: var(--neutral-alpha-weak);

  /* Lumen: a 2px corner radius on buttons, inputs, cards and menus. These are
     the design system's own radius tokens, so every component follows them. */
  --radius-xs: 2px;
  --radius-s: 2px;
  --radius-m: 2px;
  --radius-l: 2px;
  --radius-xl: 2px;

  /* Compact density: a slightly smaller header than the 56px default. */
  --header-height: 48px;
}

/* Focus rings use the brand colour. */
:focus-visible {
  outline-color: var(--brand-solid-strong);
}

/* Tabular figures keep columns of numbers aligned, like a ledger. */
.lumen-figures {
  font-variant-numeric: tabular-nums;
}
```

