import type { IconName } from "@once-ui-system/core";

export type NavLink = { href: string; label: string };
export type NavGroupEntry = { key: string; label: string; icon: IconName; items: NavLink[] };

// Analytics: Overview (the dashboard) and Reports. Workspace: Projects and Settings.
// Every href has a page: Reports shares the dashboard's home screen via /#reports? No:
// each href is a real route, so Reports is a section on the dashboard route.
export const navGroups: NavGroupEntry[] = [
  {
    key: "analytics",
    label: "Analytics",
    icon: "barChart",
    items: [
      { href: "/", label: "Overview" },
      { href: "/reports", label: "Reports" },
