  {
    key: "workspace",
    label: "Workspace",
    icon: "folder",
    items: [
      { href: "/projects", label: "Projects" },
      { href: "/settings", label: "Settings" },
    ],
  },
];

export const navLinks: (NavLink & { group: string })[] = navGroups.flatMap((g) =>
  g.items.map((item) => ({ ...item, group: g.label })),
);
